#include "backends/openssl/platform/win32/pst_openssl_system_trust_win32.h"
#include <stdio.h>
#include <stdlib.h>
#define CHECK(x,n) if(!(x)){printf("test_openssl_system_trust_win32: FAIL %d\n",n);return n;}
static unsigned char *load(const char *path,pst_size *size){FILE*f;long n;unsigned char*p;*size=0;f=fopen(path,"rb");if(!f)return NULL;if(fseek(f,0,SEEK_END)||(n=ftell(f))<0||fseek(f,0,SEEK_SET)){fclose(f);return NULL;}p=(unsigned char*)malloc((size_t)n);if(!p){fclose(f);return NULL;}if(n&&fread(p,1,(size_t)n,f)!=(size_t)n){free(p);fclose(f);return NULL;}fclose(f);*size=(pst_size)n;return p;}
int main(int argc,char **argv){unsigned char*leaf,*intermediate;pst_size leaf_size,intermediate_size;pst_ossl_windows_certificate item;pst_ossl_windows_trust_detail detail,observed;pst_u8 bad[3]={1,2,3};pst_u32 result;if(argc!=3)return 2;leaf=load(argv[1],&leaf_size);intermediate=load(argv[2],&intermediate_size);CHECK(leaf&&intermediate,1);item.der=intermediate;item.der_size=intermediate_size;result=pst_ossl_windows_system_trust_evaluate(leaf,leaf_size,&item,1,&detail);observed=detail;CHECK(result==PST_OSSL_WINDOWS_TRUST_CERTIFICATE_REJECTED,2);CHECK(detail.chain_api_succeeded,3);CHECK(detail.chain_error_present||detail.policy_error_present,4);CHECK(detail.policy_api_succeeded,5);CHECK(pst_ossl_windows_system_trust_evaluate(bad,sizeof(bad),NULL,0,&detail)==PST_OSSL_WINDOWS_TRUST_CERTIFICATE_REJECTED,6);free(leaf);free(intermediate);printf("OPENSSL_SYSTEM_TRUST_ADAPTER=PASS PRIVATE_ROOT=REJECTED CHAIN_API=%lu CHAIN_ERROR=%lu POLICY_API=%lu POLICY_ERROR=%lu STORE_MUTATION=NONE REVOCATION_POLICY=NOT_PERFORMED\n",(unsigned long)observed.chain_api_succeeded,(unsigned long)observed.chain_error_present,(unsigned long)observed.policy_api_succeeded,(unsigned long)observed.policy_error_present);printf("test_openssl_system_trust_win32: PASS\n");return 0;}